// 구글 번역 비공식 API 호출
async function translateText(text, sourceLang, targetLang) {
  if (!text || text.trim() === "") return "";
  const url = `https://translate.googleapis.com/translate_a/single?client=gtx&sl=${sourceLang}&tl=${targetLang}&dt=t&q=${encodeURIComponent(text)}`;

  try {
    const res = await fetch(url);
    if (!res.ok) throw new Error("Translation API Response Error");
    const data = await res.json();

    if (data && data[0]) {
      let translated = "";
      data[0].forEach(item => {
        if (item[0]) translated += item[0];
      });
      return translated;
    }
    return "번역 결과를 가져오지 못했습니다.";
  } catch (err) {
    console.error("Failed to translate:", err);
    return "번역 중 오류가 발생했습니다. 다시 시도해 주세요.";
  }
}

// Tesseract.js 라이브러리 동적 로드 (Lazy Loading)
function loadTesseractLibrary() {
  return new Promise((resolve, reject) => {
    if (isTesseractLoaded) {
      resolve();
      return;
    }

    const script = document.createElement("script");
    script.src = "https://cdn.jsdelivr.net/npm/tesseract.js@5.0.3/dist/tesseract.min.js";
    script.onload = () => {
      isTesseractLoaded = true;
      resolve();
    };
    script.onerror = () => {
      reject(new Error("Failed to load Tesseract.js library"));
    };
    document.head.appendChild(script);
  });
}

